{
  "findings": [
    {
      "check_id": "CKV_AZURE_23",
      "title": "Disabled critical security alerts",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "HIGH",
      "explanation": "Disabling critical security alerts such as 'Sql_Injection' and 'Data_Exfiltration' reduces the ability to detect and respond to potential security threats. These alerts should remain enabled to ensure comprehensive monitoring."
    },
    {
      "check_id": "CKV_AZURE_24",
      "title": "Short retention period for security logs",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "A retention period of 20 days may not be sufficient for forensic investigations or compliance requirements. Increasing the retention period ensures logs are available for a longer duration."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server_security_alert_policy\" \"recovery_db_alerts\" {\n  resource_group_name        = azurerm_resource_group.dr_platform.name\n  server_name                = azurerm_mssql_server.recovery_sql_server.name\n  state                      = \"Enabled\"\n  storage_endpoint           = azurerm_storage_account.backup_storage.primary_blob_endpoint\n  storage_account_access_key = azurerm_storage_account.backup_storage.primary_access_key\n  disabled_alerts = []\n  retention_days = 90\n}",
  "fix_summary": "Enabled all critical security alerts by clearing the 'disabled_alerts' list and increased the retention period for security logs from 20 days to 90 days to improve monitoring and compliance."
}
